using ContosoUniversity.Models;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_WithItems_SetsPageIndexAndTotalPages()
    {
        // Arrange
        var items = new List<string> { "A", "B", "C" };

        // Act
        var result = new PaginatedList<string>(items, 10, 2, 3);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(4, result.TotalPages); // ceil(10/3) = 4
        Assert.Equal(3, result.Count);
        Assert.Contains("A", result);
        Assert.Contains("B", result);
        Assert.Contains("C", result);
    }

    [Theory]
    [InlineData(10, 3, 4)]   // ceil(10/3) = 4
    [InlineData(9, 3, 3)]    // exact division
    [InlineData(1, 10, 1)]   // single page
    [InlineData(0, 5, 0)]    // no items
    [InlineData(100, 25, 4)] // larger set
    public void Constructor_VariousCounts_CalculatesTotalPagesCorrectly(int count, int pageSize, int expectedTotalPages)
    {
        // Arrange
        var items = new List<int>();

        // Act
        var result = new PaginatedList<int>(items, count, 1, pageSize);

        // Assert
        Assert.Equal(expectedTotalPages, result.TotalPages);
    }

    [Theory]
    [InlineData(1, false)]  // first page
    [InlineData(2, true)]   // second page
    [InlineData(3, true)]   // third page
    public void HasPreviousPage_VariousPageIndices_ReturnsExpected(int pageIndex, bool expected)
    {
        // Arrange & Act
        var result = new PaginatedList<int>(new List<int>(), 30, pageIndex, 10);

        // Assert
        Assert.Equal(expected, result.HasPreviousPage);
    }

    [Theory]
    [InlineData(1, 3, true)]   // first of 3 pages
    [InlineData(2, 3, true)]   // middle page
    [InlineData(3, 3, false)]  // last page
    [InlineData(1, 1, false)]  // only page
    public void HasNextPage_VariousPageIndices_ReturnsExpected(int pageIndex, int totalPages, bool expected)
    {
        // Arrange - count and pageSize chosen to produce desired totalPages
        int pageSize = 10;
        int count = totalPages * pageSize;

        // Act
        var result = new PaginatedList<int>(new List<int>(), count, pageIndex, pageSize);

        // Assert
        Assert.Equal(expected, result.HasNextPage);
    }

    [Fact]
    public void Create_WithQueryable_ReturnsCorrectPage()
    {
        // Arrange
        var source = Enumerable.Range(1, 50).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 2, 10);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(5, result.TotalPages);
        Assert.Equal(10, result.Count);
        Assert.Equal(11, result[0]); // first item on page 2
        Assert.Equal(20, result[9]); // last item on page 2
    }

    [Fact]
    public void Create_FirstPage_ReturnsFirstItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(10, result.Count);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_LastPartialPage_ReturnsRemainingItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 3, 10);

        // Assert
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(5, result.Count); // only 5 items on last page
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        // Arrange
        var source = Enumerable.Empty<string>().AsQueryable();

        // Act
        var result = PaginatedList<string>.Create(source, 1, 10);

        // Assert
        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.Equal(1, result.PageIndex);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Constructor_AddsAllItemsToList()
    {
        // Arrange
        var items = new List<string> { "alpha", "beta", "gamma" };

        // Act
        var result = new PaginatedList<string>(items, 3, 1, 10);

        // Assert
        Assert.Equal(3, result.Count);
        Assert.Equal("alpha", result[0]);
        Assert.Equal("beta", result[1]);
        Assert.Equal("gamma", result[2]);
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain any existing notifications from the static queue (shared across tests)
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_ValidInput_EnqueuesNotification()
    {
        // Arrange & Act
        _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutUserName_DefaultsToSystem()
    {
        // Act
        _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
    {
        // Act
        _sut.SendNotification("Department", "5", "Engineering", operation, "user1");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains(expectedVerb, notification.Message);
        Assert.Contains("Engineering", notification.Message);
    }

    [Fact]
    public void SendNotification_WithDisplayName_IncludesNameInMessage()
    {
        // Act
        _sut.SendNotification("Student", "42", "Jane Smith", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Jane Smith", notification.Message);
        Assert.DoesNotContain("ID: 42", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_IncludesIdInMessage()
    {
        // Act
        _sut.SendNotification("Student", "42", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
    }

    [Fact]
    public void SendNotification_NullDisplayName_IncludesIdInMessage()
    {
        // Act
        _sut.SendNotification("Student", "42", null, EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
    }

    [Fact]
    public void SendNotification_WhitespaceDisplayName_IncludesIdInMessage()
    {
        // Act
        _sut.SendNotification("Student", "42", "   ", EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Act
        var result = _sut.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_MultipleEnqueued_ReturnsFIFOOrder()
    {
        // Arrange
        _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);
        _sut.SendNotification("Department", "3", "Third", EntityOperation.DELETE);

        // Act & Assert
        var first = _sut.ReceiveNotification();
        Assert.Equal("Student", first!.EntityType);
        Assert.Equal("1", first.EntityId);

        var second = _sut.ReceiveNotification();
        Assert.Equal("Course", second!.EntityType);
        Assert.Equal("2", second.EntityId);

        var third = _sut.ReceiveNotification();
        Assert.Equal("Department", third!.EntityType);
        Assert.Equal("3", third.EntityId);

        // Queue should now be empty
        Assert.Null(_sut.ReceiveNotification());
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        // Arrange
        var before = DateTime.Now.AddSeconds(-1);

        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.True(notification.CreatedAt >= before);
        Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // Act & Assert (no-op implementation, should not throw)
        var exception = Record.Exception(() => _sut.MarkAsRead(1));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        // Act & Assert
        var exception = Record.Exception(() => _sut.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_OverloadWithoutDisplayName_EnqueuesCorrectly()
    {
        // Act
        _sut.SendNotification("Instructor", "7", EntityOperation.DELETE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("7", notification.EntityId);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Equal("admin", notification.CreatedBy);
    }
}

