using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Student CreateStudent(string firstName = "John", string lastName = "Doe", DateTime? enrollmentDate = null)
    {
        return new Student
        {
            FirstMidName = firstName,
            LastName = lastName,
            EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
        };
    }

    private void SeedStudents(params Student[] students)
    {
        _context.Students.AddRange(students);
        _context.SaveChanges();
    }

    #region Index Tests

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
    {
        // Arrange
        SeedStudents(
            CreateStudent("Charlie", "Zulu"),
            CreateStudent("Alice", "Alpha"),
            CreateStudent("Bob", "Mike")
        );

        // Act
        var result = _controller.Index(null, null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
        Assert.Equal("Alpha", model[0].LastName);
        Assert.Equal("Mike", model[1].LastName);
        Assert.Equal("Zulu", model[2].LastName);
    }

    [Fact]
    public void Index_SortByNameDesc_ReturnsStudentsInDescendingOrder()
    {
        // Arrange
        SeedStudents(
            CreateStudent("Alice", "Alpha"),
            CreateStudent("Bob", "Zulu")
        );

        // Act
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Zulu", model[0].LastName);
        Assert.Equal("Alpha", model[1].LastName);
    }

    [Fact]
    public void Index_SortByDate_ReturnsStudentsOrderedByEnrollmentDate()
    {
        // Arrange
        SeedStudents(
            CreateStudent("Late", "Student", new DateTime(2024, 1, 1)),
            CreateStudent("Early", "Student2", new DateTime(2020, 1, 1))
        );

        // Act
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Student2", model[0].LastName);
        Assert.Equal("Student", model[1].LastName);
    }

    [Fact]
    public void Index_SortByDateDesc_ReturnsStudentsOrderedByEnrollmentDateDescending()
    {
        // Arrange
        SeedStudents(
            CreateStudent("Late", "Student", new DateTime(2024, 1, 1)),
            CreateStudent("Early", "Student2", new DateTime(2020, 1, 1))
        );

        // Act
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Student", model[0].LastName);
        Assert.Equal("Student2", model[1].LastName);
    }

    [Fact]
    public void Index_SearchByLastName_FiltersCorrectly()
    {
        // Arrange
        SeedStudents(
            CreateStudent("John", "Smith"),
            CreateStudent("Jane", "Doe"),
            CreateStudent("Bob", "Smith")
        );

        // Act
        var result = _controller.Index(null, null, "Smith", null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(2, model.Count);
        Assert.All(model, s => Assert.Equal("Smith", s.LastName));
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersCorrectly()
    {
        // Arrange
        SeedStudents(
            CreateStudent("John", "Smith"),
            CreateStudent("Jane", "Doe"),
            CreateStudent("John", "Adams")
        );

        // Act
        var result = _controller.Index(null, null, "John", null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(2, model.Count);
        Assert.All(model, s => Assert.Equal("John", s.FirstMidName));
    }

    [Fact]
    public void Index_SearchStringNotNull_ResetsPageTo1()
    {
