    {
        // Arrange
        var dept = CreateDepartment();
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = CreateCourse(2002, "Test Course", dept.DepartmentID);
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("document.exe");
        mockFile.Setup(f => f.Length).Returns(1024);

        // Act
        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var error = _controller.ModelState["teachingMaterialImage"]!.Errors.First();
        Assert.Contains("valid image file", error.ErrorMessage);
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsViewWithError()
    {
        // Arrange
        var dept = CreateDepartment();
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = CreateCourse(2003, "Large File Course", dept.DepartmentID);
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("photo.jpg");
        mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit

        // Act
        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var error = _controller.ModelState["teachingMaterialImage"]!.Errors.First();
        Assert.Contains("5MB", error.ErrorMessage);
    }

