using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new NotificationsController(_context);
        // Drain existing notifications from static queue
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    #region GetNotifications Tests

    [Fact]
    public void GetNotifications_NoNotifications_ReturnsEmptyListWithSuccess()
    {
        // Act
        var result = _controller.GetNotifications();

        // Assert
        Assert.NotNull(result);
        var json = result.Value;
        Assert.NotNull(json);
        // Verify it has the expected shape via dynamic/reflection
        var type = json.GetType();
        var successProp = type.GetProperty("success");
        var countProp = type.GetProperty("count");
        Assert.True((bool)successProp!.GetValue(json)!);
        Assert.Equal(0, (int)countProp!.GetValue(json)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotificationsAndCount()
    {
        // Arrange - enqueue some notifications via the service
        var svc = new NotificationService();
        svc.SendNotification("Student", "1", "John", EntityOperation.CREATE);
        svc.SendNotification("Course", "101", "Math", EntityOperation.UPDATE);
        svc.Dispose();

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var json = result.Value!;
        var type = json.GetType();
        var successProp = type.GetProperty("success");
        var countProp = type.GetProperty("count");
        Assert.True((bool)successProp!.GetValue(json)!);
        Assert.Equal(2, (int)countProp!.GetValue(json)!);
    }

    [Fact]
    public void GetNotifications_MoreThan10_LimitsTo10()
    {
        // Arrange
        var svc = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            svc.SendNotification("Entity", i.ToString(), $"Name{i}", EntityOperation.CREATE);
        }
        svc.Dispose();

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var json = result.Value!;
        var type = json.GetType();
        var countProp = type.GetProperty("count");
        Assert.Equal(10, (int)countProp!.GetValue(json)!);
    }

    #endregion

    #region MarkAsRead Tests

    [Fact]
    public void MarkAsRead_ValidId_ReturnsSuccess()
    {
        // Act
        var result = _controller.MarkAsRead(1);

        // Assert
        var json = result.Value!;
        var type = json.GetType();
        var successProp = type.GetProperty("success");
        Assert.True((bool)successProp!.GetValue(json)!);
    }

    #endregion

    #region Index Tests

    [Fact]
    public void Index_ReturnsView()
    {
        // Act
        var result = _controller.Index() as ViewResult;

        // Assert
        Assert.NotNull(result);
    }

    #endregion
}

