using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns((string?)null);
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department CreateDepartment(string name = "Engineering", int id = 0)
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000m,
            StartDate = new DateTime(2020, 1, 1)
        };
        if (id > 0) dept.DepartmentID = id;
        return dept;
    }

    private Course CreateCourse(int courseId, string title, int departmentId, int credits = 3)
    {
        return new Course
        {
            CourseID = courseId,
            Title = title,
            DepartmentID = departmentId,
            Credits = credits
        };
    }

    private void SeedDepartmentAndCourses()
    {
        var dept = CreateDepartment("Computer Science");
        _context.Departments.Add(dept);
        _context.SaveChanges();

        _context.Courses.Add(CreateCourse(1001, "Intro to CS", dept.DepartmentID));
        _context.Courses.Add(CreateCourse(1002, "Data Structures", dept.DepartmentID));
        _context.SaveChanges();
    }

