+using ContosoUniversity.Models;
+
+namespace ContosoUniversity.Tests;
+
+public class ModelTests
+{
+    #region Person/Student/Instructor FullName Tests
+
+    [Theory]
+    [InlineData("Smith", "John", "Smith, John")]
+    [InlineData("Doe", "Jane", "Doe, Jane")]
+    [InlineData("O'Brien", "Mary", "O'Brien, Mary")]
+    public void Person_FullName_ReturnsConcatenatedLastNameCommaFirstName(string lastName, string firstName, string expected)
+    {
+        // Arrange
+        var student = new Student
+        {
+            LastName = lastName,
+            FirstMidName = firstName,
+            EnrollmentDate = DateTime.Now
+        };
+
+        // Act
+        var result = student.FullName;
+
+        // Assert
+        Assert.Equal(expected, result);
+    }
+
+    [Fact]
+    public void Instructor_FullName_WorksSameAsStudent()
+    {
+        // Arrange
+        var instructor = new Instructor
+        {
+            LastName = "Brown",
+            FirstMidName = "Charlie",
+            HireDate = DateTime.Now,
+            CourseAssignments = new List<CourseAssignment>()
+        };
+
+        // Act & Assert
+        Assert.Equal("Brown, Charlie", instructor.FullName);
+    }
+
+    #endregion
+
+    #region Course Model Tests
+
+    [Fact]
+    public void Course_Properties_SetCorrectly()
+    {
+        // Arrange & Act
+        var course = new Course
+        {
+            CourseID = 1050,
+            Title = "Chemistry",
+            Credits = 4,
+            DepartmentID = 3,
+            TeachingMaterialImagePath = "/path/to/image.jpg"
+        };
+
+        // Assert
+        Assert.Equal(1050, course.CourseID);
+        Assert.Equal("Chemistry", course.Title);
+        Assert.Equal(4, course.Credits);
+        Assert.Equal(3, course.DepartmentID);
+        Assert.Equal("/path/to/image.jpg", course.TeachingMaterialImagePath);
+    }
+
+    #endregion
+
+    #region Department Model Tests
+
+    [Fact]
+    public void Department_Properties_SetCorrectly()
+    {
+        // Arrange & Act
+        var dept = new Department
+        {
+            DepartmentID = 1,
+            Name = "Engineering",
+            Budget = 350000m,
+            StartDate = new DateTime(2007, 9, 1),
+            InstructorID = 5
+        };
+
+        // Assert
+        Assert.Equal(1, dept.DepartmentID);
+        Assert.Equal("Engineering", dept.Name);
+        Assert.Equal(350000m, dept.Budget);
+        Assert.Equal(new DateTime(2007, 9, 1), dept.StartDate);
+        Assert.Equal(5, dept.InstructorID);
+    }
+
+    [Fact]
+    public void Department_InstructorID_CanBeNull()
+    {
+        // Arrange & Act
+        var dept = new Department { Name = "Test", InstructorID = null };
+
+        // Assert
+        Assert.Null(dept.InstructorID);
+    }
+
+    #endregion
+
+    #region Enrollment Model Tests
+
+    [Theory]
+    [InlineData(Grade.A)]
+    [InlineData(Grade.B)]
+    [InlineData(Grade.C)]
+    [InlineData(Grade.D)]
+    [InlineData(Grade.F)]
+    public void Enrollment_Grade_AcceptsAllValues(Grade grade)
+    {
+        // Arrange & Act
+        var enrollment = new Enrollment { Grade = grade, CourseID = 1, StudentID = 1 };
+
+        // Assert
+        Assert.Equal(grade, enrollment.Grade);
+    }
+
+    [Fact]
+    public void Enrollment_Grade_CanBeNull()
+    {
+        // Arrange & Act
+        var enrollment = new Enrollment { Grade = null, CourseID = 1, StudentID = 1 };
+
+        // Assert
+        Assert.Null(enrollment.Grade);
+    }
+
+    #endregion
+
+    #region Notification Model Tests
+
+    [Fact]
+    public void Notification_Properties_SetCorrectly()
+    {
+        // Arrange
+        var now = DateTime.Now;
+        var notification = new Notification
+        {
+            Id = 1,
+            EntityType = "Student",
+            EntityId = "42",
+            Operation = "CREATE",
+            Message = "New Student created",
+            CreatedAt = now,
+            CreatedBy = "admin",
+            IsRead = false,
+            ReadAt = null
+        };
+
+        // Assert
+        Assert.Equal(1, notification.Id);
+        Assert.Equal("Student", notification.EntityType);
+        Assert.Equal("42", notification.EntityId);
+        Assert.Equal("CREATE", notification.Operation);
+        Assert.Equal("New Student created", notification.Message);
+        Assert.Equal(now, notification.CreatedAt);
+        Assert.Equal("admin", notification.CreatedBy);
+        Assert.False(notification.IsRead);
+        Assert.Null(notification.ReadAt);
+    }
+
+    [Fact]
+    public void Notification_IsRead_CanBeSetToTrue()
+    {
+        // Arrange
+        var readAt = DateTime.Now;
+        var notification = new Notification
+        {
+            IsRead = true,
+            ReadAt = readAt
+        };
+
+        // Assert
+        Assert.True(notification.IsRead);
+        Assert.Equal(readAt, notification.ReadAt);
+    }
+
+    #endregion
+
+    #region EntityOperation Enum Tests
+
+    [Fact]
+    public void EntityOperation_HasExpectedValues()
+    {
+        // Assert
+        Assert.Equal(0, (int)EntityOperation.CREATE);
+        Assert.Equal(1, (int)EntityOperation.UPDATE);
+        Assert.Equal(2, (int)EntityOperation.DELETE);
+    }
+
+    #endregion
+
+    #region OfficeAssignment Tests
+
+    [Fact]
+    public void OfficeAssignment_Properties_SetCorrectly()
+    {
+        // Arrange & Act
+        var office = new OfficeAssignment
+        {
+            InstructorID = 1,
+            Location = "Thompson 304"
+        };
+
+        // Assert
+        Assert.Equal(1, office.InstructorID);
+        Assert.Equal("Thompson 304", office.Location);
+    }
+
+    #endregion
+
+    #region CourseAssignment Tests
+
+    [Fact]
+    public void CourseAssignment_Properties_SetCorrectly()
+    {
+        // Arrange & Act
+        var assignment = new CourseAssignment
+        {
+            InstructorID = 5,
+            CourseID = 1050
+        };
+
+        // Assert
+        Assert.Equal(5, assignment.InstructorID);
+        Assert.Equal(1050, assignment.CourseID);
+    }
+
+    #endregion
+}
